#include<bits/stdc++.h>

using namespace std;
using pi=pair<int,int>;

int main(){
  int T;
  cin >> T;
  while(T--){
    int n;
    string s;
    cin >> n >> s;
    s="S"+s+"R";
    int val=0;
    vector<int> sam;
    for(int i=0;i<=n;i++){
      if(s[i]==s[i+1]){
        sam.push_back(i);
      }
      else{val++;}
    }
    val/=2;
    vector<int> d;
    d.push_back(1e8); d.push_back(1e8);
    for(int i=1;i<sam.size();i++){
      d.push_back(sam[i]-sam[i-1]);
    }
    d.push_back(1e8); d.push_back(1e8);
    int dl=d.size();
    priority_queue<pi,vector<pi>,greater<pi>> pq;
    vector<int> lef(dl),rig(dl);
    vector<int> alive(dl,1);
    for(int i=0;i<dl;i++){
      lef[i]=i-1;
      rig[i]=i+1;
      pq.push({d[i],i});
    }
    vector<int> res(n+1,0);
    int hand=0;
    res[hand]=val;
    while(val<(n/2)){
      auto od=pq.top(); pq.pop();
      if(alive[od.second]==0){continue;}
      hand+=od.first; val++;
      res[hand]=val;
      int el=lef[od.second];
      int er=rig[od.second];
      d[od.second]=d[el]+d[er]-d[od.second];
      pq.push({d[od.second],od.second});
      {
        alive[el]=0;
        int x=lef[el],y=rig[el];
        lef[y]=x; rig[x]=y;
      }
      {
        alive[er]=0;
        int x=lef[er],y=rig[er];
        lef[y]=x; rig[x]=y;
      }
    }
    for(int i=1;i<=n;i++){res[i]=max(res[i],res[i-1]);}
    for(int i=0;i<=n;i++){
      if(i){cout << " ";}
      cout << res[i];
    }cout << "\n";
  }
  return 0;
}
